     *
     * @param sceneIds 场景id列表
     * @return 被任务引用的场景信息
     */
    List<Scene> getAllReferenceScenes(@Param("sceneIds") int[] sceneIds);

    /**
     * 根据场景ID获取场景详情
     *
     * @param sceneId 场景ID
     * @return 场景详情
     */
    Scene getScene(@Param("sceneId") int sceneId);

    /**
