     *
     * @param sceneType 场景类型
     * @param cityCode 城市编码
     * @param sceneCode 场景编码
     * @return 场景详情
     */
    Scene getSceneByAddress(@Param("sceneType") int sceneType, @Param("cityCode") String cityCode,
        @Param("sceneCode") String sceneCode);

    /**
