     *
     * @param sceneIds 场景id列表
     */
    void deleteSceneByIds(@Param("sceneIds") int[] sceneIds);

    /**
     * 根据场景id列表删除对应场景
     *
     * @param sceneIds 场景id列表
     */
    void deleteSceneBySceneIds(@Param("sceneIds") int[] sceneIds);

    /**
     * 根据场景id列表删除对应场景套餐
     *
     * @param sceneIds 场景id列表
     */
    void deletePackageBySceneIds(@Param("sceneIds") int[] sceneIds);

    /**
     * 根据场景名称获取数据条数
     *
     * @param sceneName 场景名称
     * @return 场景名称数据条数
     */
    int getSceneNameCount(@Param("sceneName") String sceneName);

    /**
     * 根据场景类型、城市编码、场景编码获取数据条数
     *
     * @param sceneType 场景类型
     * @param cityCode 城市编码
     * @param sceneCode 场景编码
     * @return 场景编码数据条数
     */
    int getSceneCount(@Param("sceneType") int sceneType, @Param("cityCode") String cityCode,
        @Param("sceneCode") String sceneCode);

    /**
     * 获取新的场景ID
     *
     * @return 新的场景ID
     */
    Integer getNewSceneId();

    /**
     * 新增场馆场景
     *
     * @param scene 场景
     * @param venueInfo 场馆
     */
    void saveVenueScene(@Param("scene") Scene scene, @Param("venueInfo") VenueInfo venueInfo);

    /**
     * 新增场馆场景用户组信息
     *
     * @param sceneId 场景id
     * @param userGroups 用户组信息
     */
    void saveUserGroups(@Param("sceneId") int sceneId, @Param("userGroups") List<BackgroundUserGroup> userGroups);

    /**
     * 新增景区场景
     *
     * @param scene 场景
     */
    void saveScenicSpotScene(@Param("scene") Scene scene);

    /**
     * 保存场馆
     *
     * @param scene scene
     */
    void saveScene(@Param("scene") Scene scene);

    /**
     * 新增场景套餐
     *
     * @param bitPackageInfos 场景套餐
     * @param sceneId 场景id
     */
    void saveScenePackage(@Param("bitPackageInfos") List<BitPackageInfo> bitPackageInfos,
        @Param("sceneId") int sceneId);

    /**
     * 更新场景套餐
     *
     * @param bitPackageInfos 场景套餐
     * @param sceneId 场景id
     */
    void updateScenePackage(@Param("bitPackageInfos") List<BitPackageInfo> bitPackageInfos,
        @Param("sceneId") int sceneId);

    /**
     * 更新场馆场景
     *
     * @param scene 场景
