    /**
     * 更新场景区域信息
     *
     * @param sceneRegionInfos 需要更新的场景区域信息
     */
    void updateSceneRegionInfos(@Param("sceneRegionInfos") List<SceneRegionInfo> sceneRegionInfos);

    /**
     * 获取套餐对应QCI
     *
     * @param packageIds 套餐ID
     * @return 套餐对应QCI
     */
    Set<String> queryPackageQcis(@Param("packageIds") List<Integer> packageIds);

    /**
     * 插入场景关联小区
     *
     * @param sceneId sceneId
     * @param cellInfos cellInfos
     */
    void insertSceneCellInfos(@Param("sceneId") int sceneId, @Param("cellInfos") List<CellInfo> cellInfos);

    /**
     * 删除场景关联小区
     *
     * @param sceneId sceneId
     */
    void deleteSceneCells(@Param("sceneId") int sceneId);

    /**
     * 插入手动区域的场景的关联小区
     *
     * @param sceneId sceneId
     * @param cellInfos cellInfos
     */
    void insertManualSceneCellInfos(@Param("sceneId") int sceneId, @Param("cellInfos") List<RegionCellInfo> cellInfos);

    /**
     * 删除场景的背景用户的标识
     *
     * @param sceneId sceneId
     */
    void deleteSceneGroupLabelById(@Param("sceneId") int sceneId);

    /**
     * 保存场景的背景用户关联的标识
     *
     * @param sceneId sceneId
     * @param groupId groupId
     * @param ueGroups ueGroups
     */
    void saveSceneGroupLabelsById(@Param("sceneId") int sceneId,
                                   @Param("groupId") int groupId, @Param("ueGroups")List<UEGroupUserSLAParam> ueGroups);

    /**
     * 查询所有场景
     *
     * @return 所有场景信息
     */
    List<SceneRegionInfo> getAllScenes();

    /**
     * 插入场景关联小区
     *
     * @param cellInfos cellInfos
     */
    void insertAllSceneCells(@Param("cellInfos") List<SceneCellInfo> cellInfos);

    /**
     * 尝试创建场景任务
     *
     * @param lockName lockName
     * @param timeStamp timeStamp
     * @return 1为无任务创建，0为当前存在任务创建中
     */
    int tryLockSceneTask(@Param("lockName") String lockName, @Param("timeStamp") String timeStamp);

    /**
     * 释放创建任务锁
     *
     * @param lockName lockName
     * @param timeStamp timeStamp
     */
    void tryUnlockSceneTask(@Param("lockName") String lockName, @Param("timeStamp") String timeStamp);

    /**
     * 释放创建任务锁
     *
     * @param lockName lockName
     * @param threshold threshold
     * @return 清理结果
     */
    int clearExpiredLocks(@Param("lockName") String lockName, @Param("threshold") String threshold);
}
